const tabId = 1962625075;
const layoutInfo = await browserjs(tabId, () => {
  const el = document.getElementById('ddlYearMin');
  let curr = el;
  const path = [];
  while (curr && curr !== document.body) {
    const r = curr.getBoundingClientRect();
    const style = window.getComputedStyle(curr);
    path.push({
      tag: curr.tagName,
      id: curr.id,
      className: curr.className,
      rect: { width: r.width, height: r.height, top: r.top, left: r.left },
      display: style.display,
      visibility: style.visibility
    });
    curr = curr.parentElement;
  }
  return {
    window: { innerWidth: window.innerWidth, innerHeight: window.innerHeight },
    path
  };
});
console.log("Layout path:", JSON.stringify(layoutInfo, null, 2));

