const tabId = 1962625075;
const listings = await browserjs(tabId, () => {
  // Let's inspect the listings
  // Look for elements containing vehicle titles / specs / prices
  const items = Array.from(document.querySelectorAll('.search-result, .search-results__item, [class*="search-result"]')).filter(el => {
    return el.querySelector('h2, h3, .price, [class*="price"], [class*="title"]');
  });

  if (items.length === 0) {
    // Let's find h2/h3 elements that look like vehicle listings
    const headings = Array.from(document.querySelectorAll('h2, h3')).map(h => {
      const parent = h.closest('article, div[class*="item"], div[class*="result"], li, section') || h.parentElement;
      return {
        title: h.textContent.trim(),
        text: parent ? parent.textContent.replace(/\s+/g, ' ').trim().slice(0, 300) : '',
        link: h.querySelector('a')?.href || parent?.querySelector('a')?.href
      };
    });
    return { type: "headings", data: headings.slice(0, 10) };
  }

  return {
    type: "items",
    data: items.slice(0, 10).map(item => ({
      title: item.querySelector('h2, h3, [class*="title"]')?.textContent.trim(),
      price: item.querySelector('[class*="price"]')?.textContent.trim(),
      details: item.textContent.replace(/\s+/g, ' ').trim().slice(0, 300),
      url: item.querySelector('a')?.href
    }))
  };
});
console.log("Listings:", JSON.stringify(listings, null, 2));

